package application

import "github.com/skillicinski/bo/internal/agent"

type SynthesisOptions struct {
	// SynthesisOptions contains bounded per-agent-runtime limits. Provider credentials and
	// model selection belong to the composition root and provider adapter. RuntimeTimeoutSeconds
	// limits one agent runtime; the caller context controls the complete workflow.
	MaxTurns              int
	MaxToolCalls          int
	MaxToolOutputBytes    int
	MaxResponseTokens     int
	RuntimeTimeoutSeconds int
}

type SynthesisResult struct {
	SummariesWritten int           `json:"summaries_written"`
	SummariesSkipped int           `json:"summaries_skipped"`
	Committed        []Operation   `json:"-"`
	Metrics          agent.Metrics `json:"metrics"`
}

type SynthMode string

const (
	SynthModeDefault   SynthMode = ""
	SynthModeSummarize SynthMode = "summarize"
	SynthModeDistill   SynthMode = "distill"
)

type SynthResult struct {
	SummariesWritten    int
	SummariesSkipped    int
	DistillationWritten int
	DistillationSkipped int
	Committed           []Operation
	Metrics             agent.Metrics
}

func DefaultSynthesisOptions() SynthesisOptions {
	defaults := agent.DefaultOptions()
	return SynthesisOptions{
		MaxTurns: defaults.MaxTurns, MaxToolCalls: defaults.MaxToolCalls,
		MaxToolOutputBytes: defaults.MaxToolOutputBytes, MaxResponseTokens: defaults.MaxResponseTokens,
		RuntimeTimeoutSeconds: 120,
	}
}
package application

import (
	"context"
	"crypto/sha256"
	"encoding/hex"
	"fmt"

	"github.com/skillicinski/bo/internal/domain"
	internalerrors "github.com/skillicinski/bo/internal/errors"
)

// Revision is an opaque workspace version. Callers can only compare it or
// pass it back to a workspace implementation.
type Revision struct{ digest [sha256.Size]byte }

func NewRevision(data []byte) Revision { return Revision{digest: sha256.Sum256(data)} }

func RevisionFromString(value string) (Revision, error) {
	data, err := hex.DecodeString(value)
	if err != nil || len(data) != sha256.Size {
		return Revision{}, internalerrors.Validation("invalid revision")
	}
	var digest [sha256.Size]byte
	copy(digest[:], data)
	return Revision{digest: digest}, nil
}

func (r Revision) Equal(other Revision) bool { return r == other }
func (r Revision) IsZero() bool              { return r == Revision{} }
func (r Revision) String() string            { return hex.EncodeToString(r.digest[:]) }

type SnapshotCommit = domain.SnapshotCommit
type SummaryCommit = domain.SummaryCommit
type DistillationCommit = domain.DistillationCommit

// Workspace is the persistence boundary for one workspace.
type Workspace interface {
	Name() string
	ListDocuments(context.Context, domain.DocumentKind) ([]domain.DocumentRef, error)
	ReadDocument(context.Context, domain.DocumentRef) ([]byte, error)
	ReadState(context.Context) (domain.State, Revision, error)
	WorkspaceEvents
	CommitSnapshot(context.Context, SnapshotCommit, Revision) (domain.State, Revision, error)
	CommitSummary(context.Context, SummaryCommit, Revision) (domain.State, Revision, error)
	CommitDistillation(context.Context, DistillationCommit, Revision) (domain.State, Revision, error)
}

// WorkspaceEvents is the durable event portion of the workspace contract.
// Mutating commits carry their committed event through SnapshotCommit or
// SummaryCommit; CommitEvent is used for read-only and failed attempts.
type WorkspaceEvents interface {
	ReadEvents(context.Context, int, int) (OperationPage, error)
	// ReadRecentEvents returns at most limit of the most recent events
	// in chronological order, oldest first.
	ReadRecentEvents(context.Context, int) ([]Operation, error)
	CommitEvent(context.Context, Operation) error
}

type Operation = domain.Operation
type OperationCommand = domain.OperationCommand
type OperationOutcome = domain.OperationOutcome

const (
	CommandSeed              = domain.CommandSeed
	CommandSnap              = domain.CommandSnap
	CommandState             = domain.CommandState
	CommandSynth             = domain.CommandSynth
	CommandDistill           = domain.CommandDistill
	CommandWriteSummary      = domain.CommandWriteSummary
	CommandWriteDistillation = domain.CommandWriteDistillation
	OutcomeCommitted         = domain.OutcomeCommitted
	OutcomeFailed            = domain.OutcomeFailed
)

type OperationPage struct {
	Directory  string      `json:"directory"`
	Entries    []Operation `json:"entries"`
	Offset     int         `json:"offset"`
	Limit      int         `json:"limit"`
	NextOffset int         `json:"next_offset"`
	HasMore    bool        `json:"has_more"`
}

const MaxOperationPageLimit = 100

func ValidateOperationPageRequest(offset, limit int) error {
	if offset < 0 {
		return internalerrors.Validation("operation event offset must not be negative")
	}
	if limit < 1 || limit > MaxOperationPageLimit {
		return internalerrors.Validation(fmt.Sprintf("operation event limit must be between 1 and %d", MaxOperationPageLimit))
	}
	return nil
}

func ValidateOperationPage(page OperationPage, offset, limit int) error {
	if err := ValidateOperationPageRequest(offset, limit); err != nil {
		return err
	}
	if page.Offset < 0 || page.Offset != offset {
		return internalerrors.Validation("operation event page offset does not match request")
	}
	if page.Limit < 1 || page.Limit > MaxOperationPageLimit || page.Limit != limit {
		return internalerrors.Validation("operation event page limit does not match request")
	}
	if len(page.Entries) > page.Limit {
		return internalerrors.Validation("operation event page contains more entries than its limit")
	}
	maxInt := int(^uint(0) >> 1)
	if page.Offset > maxInt-len(page.Entries) {
		return internalerrors.Validation("operation event page cursor overflows")
	}
	if page.NextOffset != page.Offset+len(page.Entries) {
		return internalerrors.Validation("operation event page cursor does not match entries")
	}
	if page.HasMore && len(page.Entries) == 0 {
		return internalerrors.Validation("operation event page cursor does not make progress")
	}
	for index, event := range page.Entries {
		if err := event.Validate(); err != nil {
			return internalerrors.Wrap(internalerrors.KindValidation, fmt.Sprintf("operation event page entry %d is invalid", index), err)
		}
	}
	return nil
}

type OperationOptions struct {
	Actor string
}

type WorkspaceCreator interface {
	Create(context.Context, string, Operation) (string, error)
}
package application

import (
	"context"
	"errors"
	"fmt"

	"github.com/skillicinski/bo/internal/agent"
	"github.com/skillicinski/bo/internal/domain"
	internalerrors "github.com/skillicinski/bo/internal/errors"
)

func Synth(ctx context.Context, workspace Workspace, provider agent.CompletionProvider, config SynthesisOptions, mode SynthMode, options OperationOptions) (result SynthResult, returnErr error) {
	options = normalizeOperationOptions(options)
	if workspace == nil {
		return result, internalerrors.Request("workspace is not configured")
	}

	usageKnown, usageReceived := true, false
	mergeMetrics := func(metrics agent.Metrics) {
		result.Metrics.Turns += metrics.Turns
		result.Metrics.ToolCalls += metrics.ToolCalls
		result.Metrics.Duration += metrics.Duration
		if metrics.Turns == 0 {
			return
		}
		if metrics.Usage == nil {
			usageKnown = false
			return
		}
		if usageKnown {
			if result.Metrics.Usage == nil {
				result.Metrics.Usage = &agent.TokenUsage{}
			}
			result.Metrics.Usage.PromptTokens += metrics.Usage.PromptTokens
			result.Metrics.Usage.CompletionTokens += metrics.Usage.CompletionTokens
			result.Metrics.Usage.TotalTokens += metrics.Usage.TotalTokens
			usageReceived = true
		}
	}
	merge := func(summaries SynthesisResult, distill DistillResult) {
		result.SummariesWritten += summaries.SummariesWritten
		result.SummariesSkipped += summaries.SummariesSkipped
		written := distillationCount(distill)
		result.DistillationWritten += written
		result.DistillationSkipped += boolCount(distill.Skipped && written == 0)
		result.Committed = append(result.Committed, summaries.Committed...)
		result.Committed = append(result.Committed, distill.Committed...)
		mergeMetrics(summaries.Metrics)
		mergeMetrics(distill.Metrics)
	}

	switch mode {
	case SynthModeDefault, SynthModeSummarize:
		summaries, err := runSynthesis(ctx, workspace, provider, config, allSynthesisTools, options)
		merge(summaries, DistillResult{})
		returnErr = err
		if returnErr == nil && mode == SynthModeDefault {
			distill, err := runDistill(ctx, workspace, provider, config, allDistillTools, options)
			merge(SynthesisResult{}, distill)
			returnErr = err
		}
	case SynthModeDistill:
		distill, err := runDistill(ctx, workspace, provider, config, allDistillTools, options)
		merge(SynthesisResult{}, distill)
		returnErr = err
	default:
		returnErr = internalerrors.Validation(fmt.Sprintf("unknown synth mode: %s", mode))
	}
	if !usageKnown || !usageReceived {
		result.Metrics.Usage = nil
	}

	operation := newOperation(CommandSynth, options.Actor)
	operation.Metrics = &domain.OperationMetrics{
		Turns: result.Metrics.Turns, ToolCalls: result.Metrics.ToolCalls, Duration: result.Metrics.Duration,
		SummariesWritten: result.SummariesWritten, SummariesSkipped: result.SummariesSkipped,
		DistillationWritten: result.DistillationWritten, DistillationSkipped: result.DistillationSkipped,
	}
	if result.Metrics.Usage != nil {
		operation.Metrics.Usage = &domain.TokenUsage{
			PromptTokens: result.Metrics.Usage.PromptTokens, CompletionTokens: result.Metrics.Usage.CompletionTokens, TotalTokens: result.Metrics.Usage.TotalTokens,
		}
	}
	if returnErr == nil {
		operation = committedOperation(operation)
	} else {
		operation = failedOperation(operation, returnErr)
	}
	if eventErr := commitOperationEvent(ctx, workspace, operation); eventErr != nil {
		returnErr = errors.Join(returnErr, eventErr)
	}
	return result, returnErr
}
package application

import (
	"context"

	internalerrors "github.com/skillicinski/bo/internal/errors"
)

func Seed(ctx context.Context, creator WorkspaceCreator, name string, options OperationOptions) (created string, returnErr error) {
	options = normalizeOperationOptions(options)
	operation := newOperation(CommandSeed, options.Actor)
	if creator == nil {
		return "", internalerrors.Request("workspace creator is not configured")
	}
	created, returnErr = creator.Create(ctx, name, committedOperation(operation))
	returnErr = normalizeError(returnErr, internalerrors.KindFilesystem, "creating workspace")
	if returnErr != nil {
		return created, returnErr
	}
	return created, nil
}

