package main

import (
	"context"
	"fmt"
	"os"
	"strings"

	"github.com/skillicinski/bo"
	"github.com/skillicinski/bo/internal/application"
	"github.com/skillicinski/bo/internal/provider/deepseek"
	"github.com/skillicinski/bo/internal/provider/gemini"
	"github.com/skillicinski/bo/internal/storage/local"
)

const usage = "usage: bo-eval synth|distill <name> --tools all|name,name,... [--provider deepseek|gemini]"

func main() {
	if err := run(os.Args[1:]); err != nil {
		fmt.Fprintf(os.Stderr, "bo-eval failed: %s\n", err)
		os.Exit(1)
	}
}

func run(args []string) error {
	workflow, name, providerName, toolNames, err := parseWorkflowArgs(args)
	if err != nil {
		return err
	}
	if toolNames != nil {
		return runWithTools(workflow, name, providerName, toolNames)
	}

	home, err := os.UserHomeDir()
	if err != nil {
		return err
	}
	workspace, err := bo.NewLocalManager(home).Open(context.Background(), name)
	if err != nil {
		return err
	}
	defer workspace.Close()
	provider, err := publicProvider(providerName)
	if err != nil {
		return err
	}
	mode := bo.SynthModeSummarize
	if workflow == "distill" {
		mode = bo.SynthModeDistill
	}
	result, err := bo.Synth(context.Background(), bo.SynthRequest{
		Workspace: workspace,
		Provider:  provider,
		Mode:      mode,
		Options:   bo.DefaultSynthesisOptions(),
		Operations: bo.OperationOptions{Actor: "eval"},
	})
	if err != nil {
		return err
	}
	if workflow == "distill" {
		if result.DistillationWritten == 0 {
			fmt.Printf("distill skipped: %d skipped\n", result.DistillationSkipped)
		} else {
			fmt.Printf("distilled: %d documents\n", result.DistillationWritten)
		}
	} else {
		fmt.Printf("%d summaries written\n", result.SummariesWritten)
	}
	return nil
}

func runWithTools(workflow, name, providerName string, toolNames []string) error {
	apiKey, err := providerKey(providerName)
	if err != nil {
		return err
	}
	apiKey := os.Getenv("DEEPSEEK_API_KEY")
	home, err := os.UserHomeDir()
	if err != nil {
		return err
	}
	workspace, err := local.NewManager(home).Open(context.Background(), name)
	if err != nil {
		return err
	}
	defer workspace.Close()
	var provider interface {
		Complete(context.Context, application.CompletionRequest) (application.CompletionResponse, error)
	}
	_ = provider
	if providerName == "deepseek" {
		provider := deepseek.New(apiKey, os.Getenv("DEEPSEEK_API_URL"))
		if workflow == "distill" {
			result, err := application.DistillWithTools(context.Background(), workspace, provider, application.DefaultSynthesisOptions(), toolNames, application.OperationOptions{Actor: "eval"})
			if err != nil {
				return err
			}
			if result.Skipped {
				fmt.Printf("distill skipped: %s\n", result.Reason)
			} else {
				fmt.Printf("distilled: %s\n", result.Filename)
			}
			return nil
		}
		result, err := application.SynthesizeWithTools(context.Background(), workspace, provider, application.DefaultSynthesisOptions(), toolNames, application.OperationOptions{Actor: "eval"})
		if err != nil {
			return err
		}
		fmt.Printf("%d summaries written\n", result.SummariesWritten)
		return nil
	}
	provider := gemini.New(gemini.Config{APIKey: apiKey, Endpoint: os.Getenv("GEMINI_API_URL"), Model: os.Getenv("GEMINI_MODEL")})
	if workflow == "distill" {
		result, err := application.DistillWithTools(context.Background(), workspace, provider, application.DefaultSynthesisOptions(), toolNames, application.OperationOptions{Actor: "eval"})
		if err != nil {
			return err
		}
		if result.Skipped {
			fmt.Printf("distill skipped: %s\n", result.Reason)
		} else {
			fmt.Printf("distilled: %s\n", result.Filename)
		}
		return nil
	}
	result, err := application.SynthesizeWithTools(context.Background(), workspace, provider, application.DefaultSynthesisOptions(), toolNames, application.OperationOptions{Actor: "eval"})
	if err != nil {
		return err
	}
	fmt.Printf("%d summaries written\n", result.SummariesWritten)
	return nil
}

func publicProvider(name string) (bo.Provider, error) {
	apiKey, err := providerKey(name)
	if err != nil {
		return bo.Provider{}, err
	}
	switch name {
	case "deepseek":
		return bo.NewDeepSeekProvider(bo.DeepSeekConfig{
			APIKey: apiKey, Endpoint: os.Getenv("DEEPSEEK_API_URL"), Model: os.Getenv("DEEPSEEK_MODEL"),
		}), nil
	case "gemini":
		return bo.NewGeminiProvider(bo.GeminiConfig{
			APIKey: apiKey, Endpoint: os.Getenv("GEMINI_API_URL"), Model: os.Getenv("GEMINI_MODEL"),
		}), nil
	default:
		return bo.Provider{}, fmt.Errorf("%s", usage)
	}
}

func providerKey(name string) (string, error) {
	variable := ""
	switch name {
	case "deepseek":
		variable = "DEEPSEEK_API_KEY"
	case "gemini":
		variable = "GEMINI_API_KEY"
	default:
		return "", fmt.Errorf("%s", usage)
	}
	key := os.Getenv(variable)
	if key == "" {
		return "", fmt.Errorf("%s is not set", variable)
	}
	return key, nil
}

func parseArgs(args []string) (string, []string, error) {
	workflow, name, _, tools, err := parseWorkflowArgs(args)
	if err != nil || workflow != "synth" {
		return "", nil, fmt.Errorf("%s", usage)
	}
	return name, tools, nil
}

func parseWorkflowArgs(args []string) (string, string, string, []string, error) {
	if len(args) < 3 || (args[0] != "synth" && args[0] != "distill") || args[1] == "" {
		return "", "", "", nil, fmt.Errorf("%s", usage)
	}
	var toolset string
	provider := "deepseek"
	for index := 2; index < len(args); index++ {
		if index+1 >= len(args) {
			return "", "", "", nil, fmt.Errorf("%s", usage)
		}
		switch args[index] {
		case "--tools":
			if toolset != "" {
				return "", "", "", nil, fmt.Errorf("%s", usage)
			}
			toolset = args[index+1]
		case "--provider":
			if provider != "deepseek" || args[index+1] == "" {
				return "", "", "", nil, fmt.Errorf("%s", usage)
			}
			provider = args[index+1]
		default:
			return "", "", "", nil, fmt.Errorf("%s", usage)
		}
		index++
	}
	if toolset == "" {
		return "", "", "", nil, fmt.Errorf("%s", usage)
	}
	if provider != "deepseek" && provider != "gemini" {
		return "", "", "", nil, fmt.Errorf("%s", usage)
	}
	if toolset == "all" {
		return args[0], args[1], provider, nil, nil
	}
	return args[0], args[1], provider, strings.Split(toolset, ","), nil
}

