			if err != nil {
				return completionRequest{}, fmt.Errorf("user message %d: %w", index, err)
			}
			payload.Contents = append(payload.Contents, requestContent{Role: "user", Parts: []requestPart{textPart(text)}})
			lastWasTool = false
		case "assistant":
			content, err := assistantContent(message)
