def evaluate_end_to_end(
    run_path: Union[str, Path],
    api_key: Optional[str] = None,
    api_url: Optional[str] = None,
) -> dict:
    run_dir = Path(run_path)
    if not run_dir.is_dir():
        raise EvaluationError(f"result directory does not exist: {run_dir}")
    if (run_dir / "evaluation").exists():
        raise EvaluationError(f"evaluation directory already exists: {run_dir / 'evaluation'}")
    execution = _execution_metadata(run_dir, "end-to-end")
    stages = {}
    stage_documents = {}
    errors = []
    for workflow, rubric_path, rubric_label, prompt_version in (
        ("summarize", RUBRIC_PATH, "RUBRIC.md", PROMPT_VERSION),
        ("distill", DISTILL_RUBRIC_PATH, "DISTILL_RUBRIC.md", DISTILL_PROMPT_VERSION),
    ):
        metadata = _fallback_stage_metadata(run_dir, workflow, prompt_version)
        try:
            metadata, rubric = _stage_metadata(
                run_dir, workflow, rubric_path, rubric_label, prompt_version
            )
            if workflow == "summarize":
                stage, documents = _evaluate_summarize_stage(
                    run_dir, metadata, rubric, api_key, api_url
                )
            else:
                stage, documents = _evaluate_distill_stage(
                    run_dir, metadata, rubric, api_key, api_url, required=True
                )
        except EvaluationError as error:
            stage, documents = _failed_aggregate(metadata, error), []
            errors.append(error)
        stages[workflow] = stage
        stage_documents[workflow] = documents
    top = _combined_aggregate(run_dir, "end-to-end", stages, execution)
    _publish(
        run_dir,
        {workflow: (stages[workflow], stage_documents[workflow]) for workflow in stages},
        top,
    )
    if errors:
        raise errors[0]
    return top


def evaluate(
    run_path: Union[str, Path],
    api_key: Optional[str] = None,
    api_url: Optional[str] = None,
) -> dict:
    run_dir = Path(run_path)
    if not run_dir.is_dir():
        raise EvaluationError(f"result directory does not exist: {run_dir}")
    workflow = _run_workflow(run_dir)
    if workflow == "summarize":
        return evaluate_summarize(run_dir, api_key=api_key, api_url=api_url)
    if workflow == "distill":
        return evaluate_distill(run_dir, api_key=api_key, api_url=api_url)
    return evaluate_end_to_end(run_dir, api_key=api_key, api_url=api_url)


def main(argv: Optional[List[str]] = None) -> int:
    argv = sys.argv[1:] if argv is None else argv
    if len(argv) != 1:
        print("usage: BO_EVAL_API_KEY=... python3 evals/evaluate.py evals/results/<run-id>", file=sys.stderr)
        return 2
    try:
        aggregate = evaluate(argv[0])
    except EvaluationError as error:
        print(f"evaluation failed: {error}", file=sys.stderr)
        return 1
    if aggregate["status"] != "success":
        print(
            f"evaluation failed: aggregate status is {aggregate['status']}",
            file=sys.stderr,
        )
        return 1
    print(f"evaluation written: {Path(argv[0]) / 'evaluation'}")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
# Agent summary rubric

- Score each criterion from 1 to 5: 1 = fails the criterion, 2 = major problems, 3 = adequate with noticeable gaps, 4 = strong with minor gaps, and 5 = complete and consistently accurate.
- Factual faithfulness: every claim is supported by its raw document; no invented details. Preserve the source's epistemic framing by distinguishing source-reported facts, the author's experience or measurements, recommendations or opinions, and predictions or forecasts. Do not present the latter three as independently established facts.
- Coverage: every successful raw snapshot has one non-empty summary, including its main subject and useful supporting facts.
- Usefulness: summaries are concise, readable Markdown that preserves the source's important distinctions.
- Page cleanliness: summaries omit navigation, cookie notices, authoring chrome, ads, and unrelated page boilerplate.

