	if len(result.Report) == 0 {
		fmt.Println("no committed actions")
		return
	}
	for _, operation := range result.Report {
		fmt.Printf("%s:\n", operation.Operation)
		for _, document := range operation.Documents {
			fmt.Printf("  - %s\n", document.Filename)
		}
