package deepseek

import (
	"bytes"
	"context"
	"encoding/json"
	"fmt"
	"io"
	"net/http"

	"github.com/skillicinski/bo/internal/agent"
	internalerrors "github.com/skillicinski/bo/internal/errors"
)

const (
	DefaultEndpoint      = "https://api.deepseek.com/chat/completions"
	DefaultModel         = "deepseek-v4-flash"
	maxResponseBodyBytes = 1 << 20
)

type completionRequest struct {
	Model      string                `json:"model"`
	Messages   []completionMessage   `json:"messages"`
	Tools      []toolDefinition      `json:"tools,omitempty"`
	ToolChoice string                `json:"tool_choice"`
	Stream     bool                  `json:"stream"`
	MaxTokens  int                   `json:"max_tokens"`
	Thinking   thinkingConfiguration `json:"thinking"`
}

type completionMessage struct {
	Role             string     `json:"role"`
	Content          any        `json:"content"`
	Name             string     `json:"name,omitempty"`
	ToolCalls        []toolCall `json:"tool_calls,omitempty"`
	ToolCallID       string     `json:"tool_call_id,omitempty"`
	ReasoningContent any        `json:"reasoning_content,omitempty"`
}

type toolCall struct {
	ID       string       `json:"id"`
	Type     string       `json:"type"`
	Function toolFunction `json:"function"`
}

type toolFunction struct {
	Name      string `json:"name"`
	Arguments string `json:"arguments"`
}

type toolDefinition struct {
	Type     string          `json:"type"`
	Function toolDeclaration `json:"function"`
}

type toolDeclaration struct {
	Name        string         `json:"name"`
	Description string         `json:"description"`
	Parameters  map[string]any `json:"parameters"`
}

type thinkingConfiguration struct {
	Type string `json:"type"`
}

type completionResponse struct {
	Choices []completionChoice `json:"choices"`
	Usage   *usage             `json:"usage"`
}

type completionChoice struct {
	Message      *completionMessage `json:"message"`
	FinishReason *string            `json:"finish_reason"`
}

type usage struct {
	PromptTokens     int `json:"prompt_tokens"`
	CompletionTokens int `json:"completion_tokens"`
	TotalTokens      int `json:"total_tokens"`
}

type Client struct {
	APIKey     string
	Endpoint   string
	Model      string
	HTTPClient *http.Client
}

func New(apiKey, endpoint string) *Client {
	if endpoint == "" {
		endpoint = DefaultEndpoint
	}
	return &Client{APIKey: apiKey, Endpoint: endpoint, HTTPClient: &http.Client{}}
}

func (c *Client) Complete(ctx context.Context, request agent.CompletionRequest) (agent.CompletionResponse, error) {
	model := c.Model
	if model == "" {
		model = DefaultModel
	}
	body, err := json.Marshal(completionRequest{
		Model: model, Messages: wireMessages(request.Messages), Tools: wireTools(request.Tools),
		ToolChoice: "auto", MaxTokens: request.MaxTokens,
		Thinking: thinkingConfiguration{Type: "disabled"},
	})
	if err != nil {
		return agent.CompletionResponse{}, internalerrors.ProviderTransport("encoding API request failed", err)
	}
	endpoint := c.Endpoint
	if endpoint == "" {
		endpoint = DefaultEndpoint
	}
	httpClient := c.HTTPClient
	if httpClient == nil {
		httpClient = &http.Client{}
	}
	req, err := http.NewRequestWithContext(ctx, http.MethodPost, endpoint, bytes.NewReader(body))
	if err != nil {
		return agent.CompletionResponse{}, internalerrors.ProviderTransport("creating API request failed", err)
	}
	req.Header.Set("Authorization", "Bearer "+c.APIKey)
	req.Header.Set("Content-Type", "application/json")
	response, err := httpClient.Do(req)
	if err != nil {
		if contextErr := internalerrors.Context(err); contextErr != nil {
			return agent.CompletionResponse{}, contextErr
		}
		return agent.CompletionResponse{}, internalerrors.TransientProviderTransport("API request failed", err)
	}
	defer response.Body.Close()
	if response.StatusCode < 200 || response.StatusCode >= 300 {
		data, _ := io.ReadAll(io.LimitReader(response.Body, 512))
		retryable := response.StatusCode == http.StatusTooManyRequests || response.StatusCode >= http.StatusInternalServerError
		return agent.CompletionResponse{}, internalerrors.ProviderRejected(fmt.Sprintf("provider returned HTTP %d: %s", response.StatusCode, string(data)), retryable)
	}
	data, err := io.ReadAll(io.LimitReader(response.Body, maxResponseBodyBytes+1))
	if err != nil {
		if contextErr := internalerrors.Context(err); contextErr != nil {
			return agent.CompletionResponse{}, contextErr
		}
		return agent.CompletionResponse{}, internalerrors.TransientProviderTransport("reading API response failed", err)
	}
	if len(data) > maxResponseBodyBytes {
		return agent.CompletionResponse{}, internalerrors.ProviderMalformed("API response exceeds size limit", nil)
	}
	var payload completionResponse
	if err := json.Unmarshal(data, &payload); err != nil {
		return agent.CompletionResponse{}, internalerrors.ProviderMalformed("malformed API response", err)
	}
	if len(payload.Choices) == 0 {
		return agent.CompletionResponse{}, internalerrors.ProviderMalformed("malformed API response: missing choices[0].message", nil)
	}
	choice := payload.Choices[0]
	if choice.Message == nil || choice.Message.Role != "assistant" {
		return agent.CompletionResponse{}, internalerrors.ProviderMalformed("malformed API response: invalid choices[0].message", nil)
	}
	if choice.Message.Content != nil {
		if _, ok := choice.Message.Content.(string); !ok {
			return agent.CompletionResponse{}, internalerrors.ProviderMalformed("malformed API response: message.content must be a string or null", nil)
		}
	}
	if choice.FinishReason == nil {
		return agent.CompletionResponse{}, internalerrors.ProviderMalformed("malformed API response: invalid choices[0].finish_reason", nil)
	}
	if err := validateToolCalls(choice.Message.ToolCalls); err != nil {
		return agent.CompletionResponse{}, internalerrors.ProviderMalformed("malformed API response: "+err.Error(), nil)
	}
	if payload.Usage != nil && (payload.Usage.PromptTokens < 0 || payload.Usage.CompletionTokens < 0 || payload.Usage.TotalTokens < 0) {
		return agent.CompletionResponse{}, internalerrors.ProviderMalformed("malformed API response: token usage must not be negative", nil)
	}
	result := agent.CompletionResponse{Message: agentMessage(*choice.Message), Usage: agentUsage(payload.Usage)}
	if err := finishReasonError(*choice.FinishReason, len(choice.Message.ToolCalls) > 0); err != nil {
		return result, err
	}
	return result, nil
}

func wireMessages(messages []agent.ChatMessage) []completionMessage {
	if messages == nil {
		return nil
	}
	wire := make([]completionMessage, len(messages))
	for index, message := range messages {
		wire[index] = completionMessage{
			Role: message.Role, Content: message.Content, Name: message.Name, ToolCallID: message.ToolCallID,
			ToolCalls: wireToolCalls(message.ToolCalls),
		}
	}
	return wire
}

func wireToolCalls(calls []agent.ToolCall) []toolCall {
	if calls == nil {
		return nil
	}
	wire := make([]toolCall, len(calls))
	for index, call := range calls {
		wire[index] = toolCall{ID: call.ID, Type: "function", Function: toolFunction{Name: call.Function.Name, Arguments: call.Function.Arguments}}
	}
	return wire
}

func wireTools(tools []agent.ToolDefinition) []toolDefinition {
	if tools == nil {
		return nil
	}
	wire := make([]toolDefinition, len(tools))
	for index, tool := range tools {
		wire[index] = toolDefinition{Type: "function", Function: toolDeclaration{
			Name: tool.Function.Name, Description: tool.Function.Description, Parameters: tool.Function.Parameters,
		}}
	}
	return wire
}

func agentMessage(message completionMessage) agent.ChatMessage {
	return agent.ChatMessage{
		Role: message.Role, Content: message.Content, Name: message.Name, ToolCallID: message.ToolCallID,
		ToolCalls: agentToolCalls(message.ToolCalls),
	}
package agent

import (
	"context"
	"errors"
	"fmt"
	"time"
	"unicode/utf8"

	internalerrors "github.com/skillicinski/bo/internal/errors"
)

const (
	DefaultMaxTurns           = 32
	DefaultMaxToolCalls       = 64
	DefaultMaxToolOutputBytes = 65_536
	DefaultMaxResponseTokens  = 4_096
)

type Options struct {
	MaxTurns           int
	MaxToolCalls       int
	MaxToolOutputBytes int
	MaxResponseTokens  int
}

func DefaultOptions() Options {
	return Options{
		MaxTurns: DefaultMaxTurns, MaxToolCalls: DefaultMaxToolCalls,
		MaxToolOutputBytes: DefaultMaxToolOutputBytes, MaxResponseTokens: DefaultMaxResponseTokens,
	}
}

type ChatMessage struct {
	Role       string
	Content    any
	Name       string
	ToolCalls  []ToolCall
	ToolCallID string
	// ProviderMetadata is immutable provider-owned state for message replay.
	ProviderMetadata string
}

type ToolCall struct {
	ID       string
	Function ToolFunction
}

type ToolFunction struct {
	Name      string
	Arguments string
}

type ToolDefinition struct {
	Function ToolDeclaration
}

type ToolDeclaration struct {
	Name        string
	Description string
	Parameters  map[string]any
}

type CompletionRequest struct {
	Messages  []ChatMessage
	Tools     []ToolDefinition
	MaxTokens int
}

type CompletionResponse struct {
	Message ChatMessage
	Usage   *TokenUsage
}

type TokenUsage struct {
	PromptTokens     int
	CompletionTokens int
	TotalTokens      int
}

type CompletionProvider interface {
	Complete(context.Context, CompletionRequest) (CompletionResponse, error)
}

type Tool struct {
	Definition ToolDefinition
	Execute    func(context.Context, ToolCall) (string, error)
}

type Runtime struct {
	Provider CompletionProvider
	Tools    []Tool
	Done     func() bool
}

type Metrics struct {
	Turns     int           `json:"turns"`
	ToolCalls int           `json:"tool_calls"`
	Usage     *TokenUsage   `json:"usage,omitempty"`
	Duration  time.Duration `json:"duration"`
}

type Result struct {
	Messages []ChatMessage
	Message  ChatMessage
	Metrics
}

func (runtime Runtime) Run(ctx context.Context, messages []ChatMessage, options Options) (Result, error) {
	started := time.Now()
	turns, toolCalls := 0, 0
	var usage TokenUsage
	usageKnown := true
	usageReceived := false
	finish := func(message ChatMessage, err error) (Result, error) {
		metrics := Metrics{Turns: turns, ToolCalls: toolCalls, Duration: time.Since(started)}
		if usageKnown && usageReceived && turns > 0 {
			metrics.Usage = &usage
		}
		return Result{Messages: messages, Message: message, Metrics: metrics}, err
	}
	if runtime.Provider == nil {
		return finish(ChatMessage{}, internalerrors.Request("agent provider is not configured"))
	}
	options = normalizedOptions(options)
	var lastToolError error
	terminalError := func(fallback, batchError error) error {
		if batchError != nil {
			return batchError
		}
		if lastToolError != nil {
			return lastToolError
		}
		return fallback
	}
	definitions := make([]ToolDefinition, 0, len(runtime.Tools))
	executors := make(map[string]func(context.Context, ToolCall) (string, error), len(runtime.Tools))
	for _, tool := range runtime.Tools {
		name := tool.Definition.Function.Name
		definitions = append(definitions, tool.Definition)
		executors[name] = tool.Execute
	}
	for {
		if err := ctx.Err(); err != nil {
			return finish(ChatMessage{}, internalerrors.Context(err))
		}
		if turns >= options.MaxTurns {
			return finish(ChatMessage{}, terminalError(internalerrors.ProviderMalformed(fmt.Sprintf("max turns reached (%d)", options.MaxTurns), nil), nil))
		}
		turns++
		response, err := runtime.Provider.Complete(ctx, CompletionRequest{
			Messages: messages, Tools: definitions, MaxTokens: options.MaxResponseTokens,
		})
		if response.Usage != nil && usageKnown {
			usage.PromptTokens += response.Usage.PromptTokens
			usage.CompletionTokens += response.Usage.CompletionTokens
			usage.TotalTokens += response.Usage.TotalTokens
			usageReceived = true
		} else if err == nil {
			usageKnown = false
		}
		if err != nil {
			return finish(ChatMessage{}, providerError(err))
		}
		message := response.Message
		if message.Role == "" {
			message.Role = "assistant"
		}
		if len(message.ToolCalls) > 0 {
			messages = append(messages, message)
			batchToolError := error(nil)
			for _, call := range message.ToolCalls {
				if toolCalls >= options.MaxToolCalls {
					return finish(message, terminalError(internalerrors.ProviderMalformed(fmt.Sprintf("max tool calls reached (%d)", options.MaxToolCalls), nil), batchToolError))
				}
				toolCalls++
				if call.ID == "" {
					return finish(message, internalerrors.ProviderMalformed("assistant tool call has no id", nil))
				}
				execute, ok := executors[call.Function.Name]
				var output string
				var toolErr error
				if !ok {
					toolErr = fmt.Errorf("unsupported tool: %s", call.Function.Name)
				} else if execute == nil {
					toolErr = fmt.Errorf("tool is not configured: %s", call.Function.Name)
				} else {
					output, toolErr = execute(ctx, call)
				}
				if toolErr != nil {
					var categorized *internalerrors.Error
					if errors.As(toolErr, &categorized) {
						batchToolError = toolErr
					}
					output = "ERROR: " + toolErr.Error()
				}
				messages = append(messages, ChatMessage{Role: "tool", ToolCallID: call.ID, Content: BoundedOutput(output, options.MaxToolOutputBytes)})
			}
			lastToolError = batchToolError
			if runtime.Done != nil && runtime.Done() {
				return finish(message, lastToolError)
			}
			continue
		}
		messages = append(messages, message)
		return finish(message, lastToolError)
	}
}

func providerError(err error) error {
	var categorized *internalerrors.Error
	if errors.As(err, &categorized) {
		return err
	}
	if contextErr := internalerrors.Context(err); contextErr != nil {
		return contextErr
	}
	return internalerrors.ProviderTransport(err.Error(), err)
}

