func runSeed(args []string) {
	name := ""
	for index := 0; index < len(args); index++ {
		if args[index] != "--name" || name != "" {
			fail("seeding", "usage: bo seed [--name <name>]")
		}
		if index+1 >= len(args) {
			fail("seeding", "missing value for --name")
		}
		name = args[index+1]
		index++
	}
	home, err := os.UserHomeDir()
	if err != nil {
