}

func runSnap(args []string) {
	if len(args) < 2 || strings.HasPrefix(args[0], "-") {
		fail("snap", "usage: bo snap <dir> <source>...")
	}
	home, err := os.UserHomeDir()
	if err != nil {
		fail("snap", err.Error())
	}
	workspace, err := bo.NewLocalManager(home).Open(context.Background(), args[0])
	if err != nil {
