		fail("snap", err.Error())
	}
	defer workspace.Close()
	result, err := bo.Snap(context.Background(), bo.SnapRequest{
		Workspace:  workspace,
		Sources:    args[1:],
		Operations: bo.OperationOptions{Actor: "cli"},
