def _safe_markdown_filename(filename: object, label: str) -> str:
    if not isinstance(filename, str) or not filename:
        raise EvaluationError(f"{label} must be a Markdown file name")
    path = Path(filename)
    if (
        path.name != filename
        or "/" in filename
        or "\\" in filename
        or path.suffix.lower() != ".md"
    ):
        raise EvaluationError(f"{label} must be a Markdown file name")
    return filename


