set -eu

repo=$(CDPATH= cd -- "$(dirname -- "$0")/.." && pwd)
bo=${BO_BIN:-$repo/bin/bo}
bo_eval=${BO_EVAL_BIN:-$repo/bin/bo-eval}
usage='usage: ./evals/run.sh [--workflow summarize|distill|end-to-end] [--corpus name.txt|path] [--tools all|name,name,...] [--provider deepseek|gemini]'

workflow=end-to-end
corpus=$repo/evals/corpora/default.txt
toolset=all
provider=deepseek
while [ "$#" -gt 0 ]; do
	case "$1" in
		--workflow)
			[ "$#" -eq 1 ] && { printf '%s\n' "$usage" >&2; exit 2; }
			case "$2" in
				summarize|distill|end-to-end) workflow=$2 ;;
				*) printf '%s\n' "$usage" >&2; exit 2 ;;
			esac
			shift 2
			;;
		--corpus)
			[ "$#" -eq 1 ] && { printf '%s\n' "$usage" >&2; exit 2; }
			case "$2" in
				*/*) corpus=$2 ;;
				*) corpus=$repo/evals/corpora/$2 ;;
			esac
			shift 2
			;;
		--tools)
			[ "$#" -eq 1 ] && { printf '%s\n' "$usage" >&2; exit 2; }
			toolset=$2
			shift 2
			;;
		--provider)
			[ "$#" -eq 1 ] && { printf '%s\n' "$usage" >&2; exit 2; }
			case "$2" in
				deepseek|gemini) provider=$2 ;;
				*) printf '%s\n' "$usage" >&2; exit 2 ;;
