            "BO_EVAL_WORKSPACE_NAME": WORKSPACE_NAME,
            "BO_EVAL_TASK": str(trial_dir.parent.parent / "task.json"),
            "BO_EVAL_WORKFLOW": workflow,
            "BO_EVAL_PROVIDER": provider,
        }
