        with stage_stdout.open("wb") as stdout, stage_stderr.open("wb") as stderr:
            try:
                result = subprocess.run(actual_command, cwd=ROOT, env=environment, stdout=stdout, stderr=stderr, timeout=timeout)
                exit_code = result.returncode
            except subprocess.TimeoutExpired:
                timed_out = True
            except OSError as error:
                process_error = f"stage {index}: {error}"
        if workflow == "end-to-end" and index == 1 and exit_code == 0:
            try:
                summary_baseline = file_hashes(workspace / "summaries")
