        return None
    if timed_out:
        return "runtime"
    if exit_code is None:
        return "execution"
    if result and isinstance(result.get("error"), dict):
        kind = result["error"].get("kind", "")
        if str(kind).startswith("provider_"):
            return "provider"
        if kind in ("deadline", "canceled"):
