// ApplySnapshot returns the state after a raw document commit.
func (s State) ApplySnapshot(commit SnapshotCommit) (State, error) {
	if err := commit.Validate(); err != nil {
		return State{}, err
	}
	state, err := internalState(s)
	if err != nil {
		return State{}, publicError(err)
	}
	next, err := state.ApplySnapshot(internalSnapshotCommit(commit))
	if err != nil {
		return State{}, publicError(err)
	}
	result, err := publicState(next)
	return result, publicError(err)
}

